function longestSubstring(str) {
  let max = 0, start = 0;
  const seen = new Map();
  for (let i = 0; i < str.length; i++) {
    if (seen.has(str[i]) && seen.get(str[i]) >= start) {
      start = seen.get(str[i]) + 1;
    }
    seen.set(str[i], i);
    max = Math.max(max, i - start + 1);
  }
  return max;
}
